package com.ellenco.platform.domain;
import jakarta.persistence.*;import java.time.LocalDateTime;import java.util.*;
@Entity @Table(name="inventarios") public class InventoryCount{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)@JoinColumn(name="galpao_id")private Warehouse galpao;private String status="EM_CONTAGEM";private String responsavel;private boolean contagemCega=true;private LocalDateTime iniciadoEm=LocalDateTime.now();private LocalDateTime enviadoEm;private LocalDateTime aprovadoEm;private String aprovadoPor;@OneToMany(mappedBy="inventario",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER)private List<InventoryCountItem> itens=new ArrayList<>();
 public Long getId(){return id;}public Warehouse getGalpao(){return galpao;}public void setGalpao(Warehouse v){galpao=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public String getResponsavel(){return responsavel;}public void setResponsavel(String v){responsavel=v;}public boolean isContagemCega(){return contagemCega;}public void setContagemCega(boolean v){contagemCega=v;}public LocalDateTime getIniciadoEm(){return iniciadoEm;}public LocalDateTime getEnviadoEm(){return enviadoEm;}public void setEnviadoEm(LocalDateTime v){enviadoEm=v;}public LocalDateTime getAprovadoEm(){return aprovadoEm;}public void setAprovadoEm(LocalDateTime v){aprovadoEm=v;}public String getAprovadoPor(){return aprovadoPor;}public void setAprovadoPor(String v){aprovadoPor=v;}public List<InventoryCountItem> getItens(){return itens;}public void setItens(List<InventoryCountItem> v){itens=v;}
}
